        add({ category: "Keywords", name: "typeid", description: "Query runtime type information.", insertText: "if (typeid(*device) == typeid(Sensor))\n{\n    /* exact dynamic type */\n}", longDescription: "typeid checks the exact dynamic type when used through a polymorphic base. Prefer virtual dispatch when it models the behavior more clearly.", symbolKind: "keyword", returnType: "keyword" });
