        add({ category: "Keywords", name: "virtual", description: "Declare a virtual member function for runtime polymorphism.", insertText: "virtual void Run() = 0;", longDescription: "virtual enables dynamic dispatch through a base pointer or reference. A polymorphic base class should generally expose a virtual destructor.", symbolKind: "keyword", returnType: "keyword" });
