        add({ category: "Qt Widgets Advanced", name: "QMainWindow with menu and toolbar", description: "Create a main window with menus, a toolbar, and a central widget.", insertText: 'class MainWindow : public QMainWindow\n{\n    Q_OBJECT\n\npublic:\n    MainWindow()\n    {\n        auto *fileMenu = menuBar()->addMenu("&File");\n        auto *openAction = fileMenu->addAction("Open");\n        auto *toolbar = addToolBar("Main");\n        toolbar->addAction(openAction);\n\n        auto *editor = new QTextEdit(this);\n        setCentralWidget(editor);\n        statusBar()->showMessage("Ready");\n    }\n};', longDescription: "A solid baseline for technical desktop tools that need menus, toolbars, and a central work area." });
        add({ category: "Qt Widgets Advanced", name: "QDialog with QDialogButtonBox", description: "Create a modal dialog with OK and Cancel buttons.", insertText: "QDialog dialog(this);\nQVBoxLayout layout(&dialog);\nQLineEdit nameEdit;\nlayout.addWidget(&nameEdit);\n\nQDialogButtonBox buttons(QDialogButtonBox::Ok | QDialogButtonBox::Cancel);\nlayout.addWidget(&buttons);\nQObject::connect(&buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);\nQObject::connect(&buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);\n\nif (dialog.exec() == QDialog::Accepted)\n{\n    qDebug() << nameEdit.text();\n}", longDescription: "Useful for compact settings panels, confirmations, and small data-entry flows." });
        add({ category: "Qt Widgets Advanced", name: "QDockWidget layout", description: "Attach a dockable panel to a main window.", insertText: 'auto *dock = new QDockWidget("Devices", this);\nauto *list = new QListWidget(dock);\ndock->setWidget(list);\naddDockWidget(Qt::LeftDockWidgetArea, dock);', longDescription: "Dock widgets are a good fit for property panels, logs, and tools around a central editor or viewer." });
        add({ category: "Qt Models & Views", name: "QStandardItemModel + QTableView", description: "Populate a table view with a simple item model.", insertText: 'auto *model = new QStandardItemModel(0, 3, this);\nmodel->setHorizontalHeaderLabels({"Name", "State", "Value"});\nmodel->appendRow({ new QStandardItem("Sensor A"), new QStandardItem("OK"), new QStandardItem("42") });\n\nauto *view = new QTableView(this);\nview->setModel(model);\nview->horizontalHeader()->setStretchLastSection(true);', longDescription: "A quick way to build operator-facing tables before moving to a custom model." });
        add({ category: "Qt Models & Views", name: "QAbstractTableModel skeleton", description: "Create a custom table model.", insertText: "class DeviceModel : public QAbstractTableModel\n{\npublic:\n    int rowCount(const QModelIndex &parent = QModelIndex()) const override\n    {\n        Q_UNUSED(parent);\n        return static_cast<int>(rows_.size());\n    }\n\n    int columnCount(const QModelIndex &parent = QModelIndex()) const override\n    {\n        Q_UNUSED(parent);\n        return 3;\n    }\n\n    QVariant data(const QModelIndex &index, int role) const override\n    {\n        if (!index.isValid() || role != Qt::DisplayRole)\n        {\n            return {};\n        }\n        return rows_[index.row()].at(index.column());\n    }\n\nprivate:\n    QVector<QVector<QVariant>> rows_;\n};", longDescription: "Custom models scale better when your data comes from live devices, databases, or asynchronous backends." });
        add({ category: "Qt State & UI Patterns", name: "custom paintEvent", description: "Draw a custom widget with QPainter.", insertText: "class GaugeWidget : public QWidget\n{\nprotected:\n    void paintEvent(QPaintEvent *) override\n    {\n        QPainter painter(this);\n        painter.setRenderHint(QPainter::Antialiasing, true);\n        painter.fillRect(rect(), QColor(24, 24, 24));\n        painter.setPen(QPen(Qt::green, 4));\n        painter.drawArc(rect().adjusted(10, 10, -10, -10), 30 * 16, 120 * 16);\n    }\n};", longDescription: "Perfect for oscilloscope-like visuals, gauges, overlays, and branding-rich widgets." });
        add({ category: "Qt I/O & Concurrency", name: "worker QObject moved to QThread", description: "Move a worker object to a thread and communicate with signals.", insertText: "class Worker : public QObject\n{\n    Q_OBJECT\npublic slots:\n    void process()\n    {\n        emit finished();\n    }\nsignals:\n    void finished();\n};\n\nauto *thread = new QThread(this);\nauto *worker = new Worker();\nworker->moveToThread(thread);\nconnect(thread, &QThread::started, worker, &Worker::process);\nconnect(worker, &Worker::finished, thread, &QThread::quit);\nconnect(worker, &Worker::finished, worker, &QObject::deleteLater);\nconnect(thread, &QThread::finished, thread, &QObject::deleteLater);\nthread->start();", longDescription: "This is the recommended Qt pattern when a worker needs an event loop or signal-based communication." });
        add({ category: "Qt File & JSON", name: "QSettings window geometry", description: "Persist and restore basic window settings.", insertText: 'QSettings settings("JerryCrozet", "JCLib");\nrestoreGeometry(settings.value("mainWindow/geometry").toByteArray());\n\nconnect(qApp, &QCoreApplication::aboutToQuit, this, [this]()\n{\n    QSettings settings("JerryCrozet", "JCLib");\n    settings.setValue("mainWindow/geometry", saveGeometry());\n});', longDescription: "A small usability improvement that users notice immediately in desktop tools." });
