        add({ category: "OpenCV ML & Tracking", name: "Kalman filter 2D", description: "Predict and correct a 2D tracked position.", insertText: "cv::KalmanFilter kf(4, 2);\nkf.transitionMatrix = (cv::Mat_<float>(4, 4) << 1,0,1,0, 0,1,0,1, 0,0,1,0, 0,0,0,1);\nsetIdentity(kf.measurementMatrix);\nsetIdentity(kf.processNoiseCov, cv::Scalar::all(1e-4));\nsetIdentity(kf.measurementNoiseCov, cv::Scalar::all(1e-2));\nsetIdentity(kf.errorCovPost, cv::Scalar::all(1));\n\ncv::Mat prediction = kf.predict();\ncv::Mat measurement = (cv::Mat_<float>(2, 1) << x, y);\nkf.correct(measurement);", longDescription: "Helpful when detections are noisy and you need smoother motion estimates." });
