        add({ category: "Arduino Core", name: "setup + loop skeleton", description: "Minimal Arduino sketch with one LED output.", insertText: `const int LED_PIN = 13;

void setup()
{
    pinMode(LED_PIN, OUTPUT);
}

void loop()
{
    digitalWrite(LED_PIN, HIGH);
    delay(200);
    digitalWrite(LED_PIN, LOW);
    delay(200);
}`, longDescription: "A very small baseline to validate a board, a toolchain, or a first hardware connection." });
        add({ category: "Arduino Core", name: "non-blocking millis timer", description: "Trigger a periodic action without using delay().", insertText: `unsigned long lastBlink = 0;
const unsigned long blinkPeriodMs = 200;

void loop()
{
    unsigned long now = millis();
    if (now - lastBlink >= blinkPeriodMs)
    {
        lastBlink = now;
        digitalWrite(LED_BUILTIN, !digitalRead(LED_BUILTIN));
    }
}`, longDescription: "millis()-based scheduling is the standard pattern once a sketch must do several things at once." });
        add({ category: "Arduino Core", name: "button debounce", description: "Debounce a push button in the main loop.", insertText: `const int BUTTON_PIN = 2;
int buttonState = HIGH;
int lastRawState = HIGH;
unsigned long lastChangeMs = 0;

void loop()
{
    int raw = digitalRead(BUTTON_PIN);
    if (raw != lastRawState)
    {
        lastRawState = raw;
        lastChangeMs = millis();
    }

    if (millis() - lastChangeMs >= 25)
    {
        buttonState = raw;
    }
}`, longDescription: "A software debounce is often enough for user inputs and avoids false multiple triggers." });
        add({ category: "Arduino Peripherals", name: "analog read to PWM", description: "Map an analog input to a PWM output.", insertText: `const int POT_PIN = A0;
const int PWM_PIN = 9;

void loop()
{
    int raw = analogRead(POT_PIN);
    int duty = map(raw, 0, 1023, 0, 255);
    analogWrite(PWM_PIN, duty);
}`, longDescription: "Classic for dimming, speed control demos, and bench interaction tools." });
        add({ category: "Arduino Core", name: "serial command parser", description: "Parse line-oriented serial commands from the Arduino Serial monitor or a host PC.", insertText: `String line;

void loop()
{
    while (Serial.available() > 0)
    {
        char c = (char)Serial.read();
        if (c == '
')
        {
            line.trim();
            if (line == "LED ON") digitalWrite(LED_BUILTIN, HIGH);
            else if (line == "LED OFF") digitalWrite(LED_BUILTIN, LOW);
            line = "";
        }
        else
        {
            line += c;
        }
    }
}`, longDescription: "A very convenient pattern when the Arduino is controlled from a PC, Raspberry Pi, or test bench script." });
        add({ category: "Arduino Core", name: "attachInterrupt event flag", description: "Capture a pulse or button edge in an interrupt.", insertText: `volatile bool eventFlag = false;

void OnInputRise()
{
    eventFlag = true;
}

void setup()
{
    pinMode(2, INPUT_PULLUP);
    attachInterrupt(digitalPinToInterrupt(2), OnInputRise, RISING);
}`, longDescription: "Keep the ISR tiny, then do heavier work later inside the main loop." });
        add({ category: "Arduino Peripherals", name: "Wire I2C sensor read", description: "Read one register with the Arduino Wire library.", insertText: `#include <Wire.h>

uint8_t ReadRegister(uint8_t address, uint8_t reg)
{
    Wire.beginTransmission(address);
    Wire.write(reg);
    Wire.endTransmission(false);
    Wire.requestFrom((int)address, 1);
    return Wire.available() ? Wire.read() : 0;
}`, longDescription: "Useful for many sensors and I2C expansion devices in Arduino projects." });
        add({ category: "Arduino Peripherals", name: "SPI peripheral transfer", description: "Exchange bytes with an SPI peripheral.", insertText: `#include <SPI.h>
const int CS_PIN = 10;

uint8_t ReadSpiRegister(uint8_t reg)
{
    digitalWrite(CS_PIN, LOW);
    SPI.transfer(reg | 0x80);
    uint8_t value = SPI.transfer(0x00);
    digitalWrite(CS_PIN, HIGH);
    return value;
}`, longDescription: "A compact and reusable baseline for SPI sensors, displays, and converters." });
        add({ category: "Arduino Core", name: "class-based device wrapper", description: "Encapsulate one peripheral or subsystem in a small C++ class.", insertText: `class LedBlinker
{
public:
    explicit LedBlinker(int pin) : pin_(pin), lastToggle_(0), state_(false) {}

    void begin()
    {
        pinMode(pin_, OUTPUT);
    }

    void update(unsigned long nowMs)
    {
        if (nowMs - lastToggle_ >= 200)
        {
            lastToggle_ = nowMs;
            state_ = !state_;
            digitalWrite(pin_, state_ ? HIGH : LOW);
        }
    }

private:
    int pin_;
    unsigned long lastToggle_;
    bool state_;
};`, longDescription: "Arduino sketches stay easier to grow when devices are wrapped in small classes instead of global state everywhere." });
        add({ category: "Arduino Core", name: "finite state machine sketch", description: "Organize sketch behavior with explicit states.", insertText: `enum class RobotState
{
    Idle,
    Search,
    Follow,
    Action
};

RobotState state = RobotState::Idle;

void loop()
{
    switch (state)
    {
        case RobotState::Idle:   if (StartRequested()) state = RobotState::Search; break;
        case RobotState::Search: if (TargetFound()) state = RobotState::Follow;    break;
        case RobotState::Follow: if (CloseEnough()) state = RobotState::Action;    break;
        case RobotState::Action: DoAction(); state = RobotState::Search;           break;
    }
}`, longDescription: "This pattern scales very well for embedded robotics and sequential control logic." });
