        add({ category: "Keywords", name: "param", description: "Parameter block for reusable PowerShell scripts.", insertText: "param(\n    [string]$ProjectRoot,\n    [switch]$VerboseMode\n)", longDescription: "A script-level parameter block is the cleanest starting point for reusable PowerShell automation." });
        add({ category: "PowerShell Basics", name: "advanced script skeleton", description: "Robust script skeleton with strict mode and error handling.", insertText: `[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [string]$ProjectRoot,
    [switch]$Clean
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

try {
    Push-Location $ProjectRoot

    if ($Clean) {
        Remove-Item -Recurse -Force build -ErrorAction SilentlyContinue
    }

    Write-Host "Working directory: $(Get-Location)"
}
catch {
    Write-Error $_
    exit 1
}
finally {
    Pop-Location
}`, longDescription: "A strong default for build, deployment, and maintenance scripts on Windows." });
        add({ category: "PowerShell Basics", name: "advanced function", description: "Reusable PowerShell function with pipeline-friendly parameters.", insertText: `function Invoke-BuildStep {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,
        [Parameter(Mandatory = $true)]
        [scriptblock]$Action
    )

    Write-Host "=== $Name ==="
    & $Action
    if ($LASTEXITCODE -ne 0) {
        throw "Step failed: $Name"
    }
}`, longDescription: "Useful when you want your PowerShell automation to read like a sequence of named operations." });
