        add({ category: "Bash Build & Deployment", name: "tar.gz release archive", description: "Create a compressed tar archive of a release directory.", insertText: `tar -czf release.tar.gz -C "$RELEASE_DIR" .`, longDescription: "Very common when packaging artifacts for Linux distribution or transfer." });
        add({ category: "Bash SSH & Networking", name: "SSH remote command", description: "Run a command on a remote Linux target.", insertText: `ssh "$USER@$HOST" "cd $REMOTE_DIR && ./build.sh"`, longDescription: "Ideal for Raspberry Pi, remote test benches, and deployment automation." });
