        add({ category: "TensorFlow Keras Advanced", name: "functional multi-input model", description: "Build a model with the Functional API.", insertText: `import tensorflow as tf

signal_input = tf.keras.Input(shape=(256, 1), name="signal")
meta_input = tf.keras.Input(shape=(4,), name="meta")
x = tf.keras.layers.Conv1D(16, 7, padding="same", activation="relu")(signal_input)
x = tf.keras.layers.GlobalAveragePooling1D()(x)
merged = tf.keras.layers.Concatenate()([x, meta_input])
output = tf.keras.layers.Dense(num_classes, activation="softmax")(merged)
model = tf.keras.Model(inputs=[signal_input, meta_input], outputs=output)`, longDescription: "The Functional API is preferable when a model has multiple inputs, outputs, or branches." });
