        add({ category: "Signal Processing & AI Pipelines", name: "end-to-end DSP to ONNX pipeline", description: "Filter, frame, feature-extract, then run ONNX inference.", insertText: `import numpy as np
from scipy import signal
import onnxruntime as ort

samples = np.asarray(signal_values, dtype=np.float32)
sos = signal.butter(4, 200.0, btype="lowpass", fs=sample_rate_hz, output="sos")
filtered = signal.sosfiltfilt(sos, samples)
frames = sliding_window_view(filtered, 256)[::128]
window = np.hanning(frames.shape[1]).astype(np.float32)
spectra = np.abs(np.fft.rfft(frames * window[None, :], axis=1)).astype(np.float32)
session = ort.InferenceSession("model.onnx", providers=["CPUExecutionProvider"])
predictions = session.run(None, {session.get_inputs()[0].name: spectra})`, longDescription: "This bridges classical DSP preprocessing and deployed AI inference in one repeatable pattern." });
        add({ category: "Signal Processing & AI Pipelines", name: "spectral image for CNN", description: "Convert a waveform into a log-spectrogram image tensor.", insertText: `import numpy as np
from scipy import signal

frequencies_hz, times_s, Zxx = signal.stft(signal_values, fs=sample_rate_hz, nperseg=256, noverlap=128)
log_power = np.log10(np.abs(Zxx) ** 2 + 1e-12)
image = log_power.astype(np.float32)[None, None, :, :]`, longDescription: "A log-spectrogram is a common bridge from 1D signals to CNN-friendly image-like inputs." });
        add({ category: "Signal Processing & AI Pipelines", name: "classification threshold sweep", description: "Evaluate how a decision threshold changes precision and recall.", insertText: `import numpy as np
from sklearn.metrics import precision_score, recall_score

for threshold in np.linspace(0.1, 0.9, 9):
    predicted = (probabilities[:, 1] >= threshold).astype(int)
    precision = precision_score(y_true, predicted)
    recall = recall_score(y_true, predicted)
    print(threshold, precision, recall)`, longDescription: "Threshold sweeps are important when the operating point matters as much as raw accuracy." });
