        add({ category: "Python Test Benches & Validation", name: "pytest parametrized tolerance test", description: "Validate a processing function against several numeric cases.", insertText: `import pytest

@pytest.mark.parametrize(
    ("value", "expected"),
    [
        (1.0, 1.0),
        (2.0, 2.0),
        (3.0, 3.0),
    ],
)
def test_identity(value: float, expected: float) -> None:
    assert value == pytest.approx(expected, rel=1e-6, abs=1e-9)`, longDescription: "Parametrized tests are a compact way to cover a family of measurement or DSP cases." });
        add({ category: "Python Test Benches & Validation", name: "pytest instrument fixture", description: "Create a fixture that opens and closes a resource.", insertText: `import pytest

class DummyInstrument:
    def write(self, command: str) -> None:
        print(command)

    def close(self) -> None:
        print("closed")

@pytest.fixture
def instrument() -> DummyInstrument:
    resource = DummyInstrument()
    try:
        yield resource
    finally:
        resource.close()`, longDescription: "Fixtures help centralize setup and teardown for instruments, sockets, and test assets." });
        add({ category: "Python Test Benches & Validation", name: "test step result dataclass", description: "Represent a bench-test result with limits and verdict.", insertText: `from dataclasses import dataclass

@dataclass(slots=True)
class StepResult:
    name: str
    measured: float
    low_limit: float
    high_limit: float

    @property
    def passed(self) -> bool:
        return self.low_limit <= self.measured <= self.high_limit`, longDescription: "A typed result object makes it easier to log, display, and export test sequences." });
        add({ category: "Python Test Benches & Validation", name: "sequence runner with stop on failure", description: "Execute named steps and abort on first failure.", insertText: `from collections.abc import Callable

Step = tuple[str, Callable[[], bool]]

def run_sequence(steps: list[Step]) -> list[tuple[str, bool]]:
    results: list[tuple[str, bool]] = []
    for name, step in steps:
        passed = step()
        results.append((name, passed))
        if not passed:
            break
    return results`, longDescription: "This pattern matches many automated bench or production validation flows." });
