        add({ category: "Python Realtime Acquisition & Bench Patterns", name: "async acquisition loop with cancellation", description: "Run an asyncio acquisition task and stop it cleanly.", insertText: `import asyncio

async def acquire(stop_event: asyncio.Event) -> None:
    while not stop_event.is_set():
        print("poll")
        await asyncio.sleep(0.1)

async def main() -> None:
    stop_event = asyncio.Event()
    task = asyncio.create_task(acquire(stop_event))
    await asyncio.sleep(1.0)
    stop_event.set()
    await task

asyncio.run(main())`, longDescription: "Async tasks are useful when mixing network I/O, UI bridges, and periodic acquisition." });
