        add({ category: "Python Distributed Acquisition & Orchestration", name: "multiprocessing producer consumer", description: "Split acquisition and processing into separate processes.", insertText: `from multiprocessing import Process, Queue
import time


def acquire(queue: Queue) -> None:
    for index in range(100):
        queue.put((time.time(), index))
    queue.put(None)


def process(queue: Queue) -> None:
    while True:
        item = queue.get()
        if item is None:
            break
        timestamp, sample = item
        print(timestamp, sample)


queue = Queue(maxsize=1024)
producer = Process(target=acquire, args=(queue,))
consumer = Process(target=process, args=(queue,))
producer.start(); consumer.start()
producer.join(); consumer.join()`, longDescription: "A robust first step when one process should stay close to hardware timing and another should do heavier analysis." });
