        add({ category: "Python Distributed Acquisition & Orchestration", name: "heartbeat monitor", description: "Track liveness of remote workers or acquisition nodes.", insertText: `import time
from collections import defaultdict

last_seen = defaultdict(lambda: 0.0)
TIMEOUT_S = 2.0


def on_heartbeat(worker_id: str) -> None:
    last_seen[worker_id] = time.monotonic()


def check_timeouts() -> list[str]:
    now = time.monotonic()
    return [worker_id for worker_id, stamp in last_seen.items() if now - stamp > TIMEOUT_S]`, longDescription: "Heartbeat monitoring is a simple and effective way to supervise distributed benches." });
