    var MAIN_WITH_ERROR_SOURCE_TEMPLATE = `{{fileHeader}}// Includes files
{{mainHeaderInclude}}#include "qpm_error.h"

//==============================================================================
// Error management
/*
    QPM_ERR_INFZ(code, message)     // Jump to error if code < 0
    QPM_ERR_INFEQZ(code, message)   // Jump to error if code <= 0
    QPM_ERR_CHCK_INFZ(expression)   // Evaluate expression and check < 0
    QPM_ERR_CHCK_INFEQZ(expression) // Evaluate expression and check <= 0
    QPM_ERR_PTR(pointer)            // Jump to error if pointer == NULL
*/

//==============================================================================
// Constants

//==============================================================================
// Types

//==============================================================================
// Static global variables

//==============================================================================
// Static functions

//==============================================================================
// Global variables

//==============================================================================
// Global functions

int main(int argc, char **argv)
{
    int status = 0;

    QpmError_InitDefaults();
    QpmError_LoadConfig("qpm_error.ini");

    //==============================================================================
    // Command-line arguments
    if (argc > 1)
    {
        const char *firstArgument = argv[1];

        if (firstArgument == NULL)
        {
            g_qpmErrorCode = -1;
            QpmError_Report(g_qpmErrorCode, "Invalid first argument", __FILE__, __LINE__, QPM_ERROR_FUNCTION);
            goto error;
        }

        /* Use firstArgument or iterate argv[1..argc-1] here. */
    }

    /* Application code starts here. */

    goto cleanup;

error:
    status = g_qpmErrorCode;

cleanup:
    return status;
}
`;
