    var PYTHON_WORKER_PROTOCOL_README_TEMPLATE = `# Python worker protocol starter

Small generic Python side of the QPM Python execution bridge.

## Files

- 'catj_py_helper.py': helper for line/JSON style stdin/stdout exchanges.
- 'example_worker.py': minimal worker loop example.
- 'logger.py': small logging helper.

This starter is intentionally generic. Project-specific robot, camera, LiDAR or ESP32 scripts are available separately in 'Robot demo Python scripts'.
`;
    var PYTHON_WORKER_HELPER_TEMPLATE = `#!/usr/bin/env python3
"""Small helper functions for QPM Python worker scripts."""

import json
import sys
from typing import Any, Dict


def send_json(payload: Dict[str, Any]) -> None:
    print(json.dumps(payload, separators=(",", ":")), flush=True)


def read_json_line() -> Dict[str, Any]:
    line = sys.stdin.readline()
    if not line:
        return {"type": "eof"}
    try:
        value = json.loads(line)
        if isinstance(value, dict):
            return value
        return {"type": "value", "value": value}
    except json.JSONDecodeError as exc:
        return {"type": "error", "message": str(exc), "raw": line.rstrip("\\n")}
`;
    var PYTHON_WORKER_LOGGER_TEMPLATE = `#!/usr/bin/env python3
"""Minimal logger for QPM Python worker scripts."""

from datetime import datetime
from pathlib import Path
from typing import Optional


class WorkerLogger:
    def __init__(self, path: Optional[str] = None) -> None:
        self.path = Path(path) if path else None

    def log(self, message: str) -> None:
        text = f"[{datetime.now().isoformat(timespec='seconds')}] {message}"
        if self.path:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            with self.path.open("a", encoding="utf-8") as stream:
                stream.write(text + "\\n")
        else:
            print(text, flush=True)
`;
    var PYTHON_WORKER_EXAMPLE_TEMPLATE = `#!/usr/bin/env python3
"""Example Python worker for the QPM Python execution bridge."""

from catj_py_helper import read_json_line, send_json
from logger import WorkerLogger


def main() -> int:
    logger = WorkerLogger()
    send_json({"type": "ready"})
    while True:
        request = read_json_line()
        if request.get("type") in {"eof", "quit", "exit"}:
            send_json({"type": "bye"})
            return 0
        logger.log(f"request={request}")
        send_json({"type": "response", "ok": True, "echo": request})


if __name__ == "__main__":
    raise SystemExit(main())
`;
    var LUA_WORKER_PROTOCOL_README_TEMPLATE = `# Lua worker protocol starter

Small generic Lua side of the QPM Lua execution bridge.

## Files

- 'example_worker.lua': minimal argument display and stdin/stdout worker loop.

## Argument access

When C calls:

'const char *args[] = { "arg1", "arg2" };'

Lua receives them as:

- 'arg[1]' = 'arg1'
- 'arg[2]' = 'arg2'

All lines printed by Lua are captured in 'QpmLuaResult.output' when using one-shot execution.
`;
    var LUA_WORKER_EXAMPLE_TEMPLATE = `-- Example Lua worker for the QPM Lua execution bridge.
-- Arguments passed from C are available in the global arg table.

local function print_arguments()
    print("Lua worker started")
    if arg ~= nil then
        for index = 1, #arg do
            print(string.format("arg[%d]=%s", index, tostring(arg[index])))
        end
    end
    io.stdout:flush()
end

local function handle_line(line)
    if line == "exit" or line == "quit" then
        print("bye")
        io.stdout:flush()
        return false
    end

    print("echo:" .. line)
    io.stdout:flush()
    return true
end

local function main()
    print_arguments()

    for line in io.lines() do
        if not handle_line(line) then
            return 0
        end
    end

    return 0
end

os.exit(main())
`;
